 plan=make(selection,b/f'K{size}',size);assert plan['actual_bundle_size']==size;assert len(set(plan['removed_pins']))==size;assert all(len(r['retained_crossing_sources'])>0 for r in plan['selected_scopes']);assert sum(len(p) for p in plan['removed_pins'].values())==len(plan['queries']);assert all(sha(p)==h for p,h in plan['source_sha256'].items());rows.append(dict(size=size,nets=[r['net'] for r in plan['selected_scopes']],pins=[r['pins'] for r in plan['selected_scopes']],min_screen_margin_ns=min(r['minimum_margin_s'] for r in plan['selected_scopes'])*1e9,request_sha256=plan['request_sha256']))
